export function findById(id) { return PROTOCOLS.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return PROTOCOLS.slice();
  return PROTOCOLS.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return PROTOCOLS.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return PROTOCOLS.filter(x => x.enabled !== false); }
export const COUNT = PROTOCOLS.length;
